package com.shopsphere.controller; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.service.CategoryService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/categories") public class CategoryController {private final CategoryService s;public CategoryController(CategoryService s){this.s=s;} @GetMapping public List<CategoryResponse> all(){return s.all();} @PostMapping @PreAuthorize("hasRole('ADMIN')") public CategoryResponse create(@Valid @RequestBody CategoryRequest r){return s.create(r);}}